<?php require $viewRoot . '/components/header.php'; ?>
<main class="scroll withnav events-page"><section class="utility-hero"><div><span class="pm-kicker">M15 · Events</span><h1>What's on in Pune</h1><p>Upcoming events with venue, neighbourhood and source provenance.</p></div></section>
<?php if($areas): ?><nav class="utility-filters"><a class="chip <?=!$selectedArea?'active':''?>" href="<?=pm_e(pm_url('/events'))?>">All Pune</a><?php foreach($areas as $area): ?><a class="chip <?=$selectedArea===$area?'active':''?>" href="<?=pm_e(pm_url('/events?area='.rawurlencode($area)))?>"><?=pm_e($area)?></a><?php endforeach; ?></nav><?php endif; ?>
<section class="utility-feed"><?php if(!$events): ?><div class="empty"><b>No upcoming published events.</b><span>Only newsroom-approved event records appear here.</span></div><?php endif; ?><?php foreach($events as $event): ?><article class="utility-card"><div class="utility-card-head"><span class="utility-kind"><?=pm_e(strtoupper($event['category']??'EVENT'))?></span><span><?=pm_e(date('D, j M · g:i A',strtotime($event['starts_at'])))?></span></div><h2><?=pm_e($event['title'])?></h2><?php if($event['summary']??''): ?><p><?=pm_e($event['summary'])?></p><?php endif; ?><div class="utility-meta"><span><?=pm_e($event['venue'])?></span><span><?=pm_e($event['area'])?></span></div><?php if($event['source_label']??''): ?><div class="utility-source">Source: <?=pm_e($event['source_label'])?></div><?php endif; ?></article><?php endforeach; ?></section></main>
